import{_ as t,l as i,o as e,c as l,v as r,p as d,x as o,d as s,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"美元主导与国际货币","description":"","frontmatter":{"title":"美元主导与国际货币","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dollar-dominance.md","filePath":"econ/dollar-dominance.md","lastUpdated":1789023840000}'),p={name:"econ/dollar-dominance.md"};function h(_,a,m,B,u,A){const n=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="美元主导与国际货币" tabindex="-1">美元主导与国际货币 <a class="header-anchor" href="#美元主导与国际货币" aria-label="Permalink to &quot;美元主导与国际货币&quot;">​</a></h1><div class="epigraph"><p>全球安全资产与贸易计价仍高度集中在美元。这是网络与政策背书，不是单一货币数量方程的世界版。</p><footer>—— Gopinath 等的计价货币；Rey 的全球金融周期；Eichengreen 对国际货币史</footer></div><p><a href="/econ/cbdc">上一课</a>把公共数字负债留在国内设计。本课收束「动态宏观与异质性」：跨境时，美元负债与美联储互换线才是真正的全球地板。公司金融进阶从下一课 ESG 另起，不在这里写治理。开放宏观的危机与互换线，贸易课序后半会再展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Rey：在资本流动下，中心国家的货币政策经风险承担渠道变成全球金融周期，浮动汇率不能完全绝缘。Gopinath：贸易以美元计价，汇率传递变弱，美国的名义冲击变成别人的实际冲击。若把「国际货币」写成铸币税口号，会漏掉：主导是发票、银行跨境负债、储备和安全资产便利收益（Du–Im–Schreger 一类）的捆绑。</p><p>缺口是给后课贸易与危机一张结构图，而不是再推一遍 NK 小国。</p><p><span class="marginnote">Gourinchas 的美元特权讨论。Maggiori, Neiman and Schreger 的货币选择。Miranda-Agrippino and Rey 的全球因子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三层：计价（贸易与金融合同）、中介（全球银行的美元负债）、官方（储备、互换）。冲击：美联储加息 → 全球 \\(\\phi\\) 收紧 → 新兴市场信用与汇率。政策：宏观审慎、资本流动管理、互换线（后课）。与主导课：美国财政–货币安排通过安全资产供给外溢。</p>',9)),(e(),d(c,null,{default:o(()=>[E(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E7%BE%8E%E5%85%83%E8%AE%A1%E4%BB%B7%22%5D%20--%3E%20PASS%5B%22%E4%BC%A0%E9%80%92%E5%87%8F%E5%BC%B1%22%5D%0A%20%20BANK%5B%22%E8%B7%A8%E5%A2%83%E7%BE%8E%E5%85%83%E8%B4%9F%E5%80%BA%22%5D%20--%3E%20GFC%5B%22%E5%85%A8%E7%90%83%E9%87%91%E8%9E%8D%E5%91%A8%E6%9C%9F%22%5D%0A%20%20RES%5B%22%E5%82%A8%E5%A4%87%E4%B8%8E%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20FLOOR%5B%22%E5%AE%98%E6%96%B9%E5%9C%B0%E6%9D%BF%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>网络外部性：别人用美元开票，你也用，以匹配成本。银行侧：欧洲银行借美元、买美元资产，美元融资紧张时全球信用收缩（Bruno–Shin）。官方侧：美债便利收益使美国能以更低 \\(r\\) 负债，同时输出安全资产短缺的另一面。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写欧元区制度史（贸易课欧元区危机）。不把去美元化写成已完成事实。CBDC 跨境结算是实验，不替代互换网络。后课默认：小国模型要声明发票货币与美元负债敞口。动态宏观补层在此封口；下一课程从<a href="/econ/npv-irr-pitfalls">NPV 与 IRR</a>起写企业项目。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>美元主导是计价、中介与官方地板的捆绑。</li><li>浮动汇率不能取消 Rey 意义上的全球周期。</li><li>出处：Rey 全球金融周期；Gopinath 计价；Bruno–Shin 美元信贷。</li></ul>',6))])}const D=t(p,[["render",h]]);export{S as __pageData,D as default};
